using namespace std;

int main() {
    string s;
    cin >> s;
    string out;
    size_t i = 0;
    while (i < s.size()) {
        // Digits can only move inside a maximal run of the same parity: sort each run descending.
        size_t j = i;
        int counts[10] = {0};
        while (j < s.size() && (s[j] - '0') % 2 == (s[i] - '0') % 2) counts[s[j++] - '0']++;
        for (int d = 9; d >= 0; d--) out.append(counts[d], char('0' + d));
