}

import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        String s = new String(System.in.readAllBytes()).strip();
        StringBuilder out = new StringBuilder();
        int i = 0, n = s.length();
        while (i < n) {
            // Digits can only move inside a maximal run of the same parity: sort each run descending.
            int j = i;
            int[] counts = new int[10];
            while (j < n && (s.charAt(j) - '0') % 2 == (s.charAt(i) - '0') % 2) counts[s.charAt(j++) - '0']++;
            for (int d = 9; d >= 0; d--) out.repeat((char) ('0' + d), counts[d]);
            i = j;
        }
        System.out.println(out);
    }
}

package main

import (
	"bufio"
	"bytes"
	"io"
	"os"
)

func main() {
	raw, _ := io.ReadAll(bufio.NewReader(os.Stdin))
	s := bytes.TrimSpace(raw)
	out := make([]byte, 0, len(s)+1)
	for i := 0; i < len(s); {
		// Digits can only move inside a maximal run of the same parity: sort each run descending.
		j := i
		var counts [10]int
		for j < len(s) && (s[j]-'0')%2 == (s[i]-'0')%2 {
			counts[s[j]-'0']++
			j++
		}
		for d := 9; d >= 0; d-- {
			for c := 0; c < counts[d]; c++ {
				out = append(out, byte('0'+d))
			}
		}
		i = j
	}
	os.Stdout.Write(append(out, '\n'))
}
